 write('author-positive-eleven.actual.receipt.json',{'role':'author','createdAt':now,'wholeChildGoals':11,'newlyAuthoredProfiles':10,'newBilingualCaseBriefs':20,'retainedMoneyProfileAndCasesByteSemanticExact':True,'retainedMoneyCandidatePath':str(SRC/'positive.money-only.candidates.json'),'retainedMoneyCandidateSha256':'sha256:'+hashlib.sha256((SRC/'positive.money-only.candidates.json').read_bytes()).hexdigest(),'totalProfiles':11,'totalBilingualCaseBriefs':22,'goalTextsAndGraphChanged':False,'proposedClassificationOnly':True,'authoritativeClassificationClaimed':False,'currentRootDenominator':303,'independentReviewClaimForTenNewProfiles':False,'humanApprovalClaim':False,'newStrictClosures':0,'restoredBindings':0})
